def solve(x):
 latest={}
 for o in x["orders"]:
  if o["id"] not in latest or o["updatedAt"]>=latest[o["id"]]["updatedAt"]: latest[o["id"]]=o
 return sorted(k for k,v in latest.items() if v["status"]!="cancelled")

